      expect(
        calc.computeShippingCents([makeLine("a", 1, 5000)], 5000),
      ).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1, 6000)], 5000),
      ).toBe(1800);
    });

    it("defaults to heaviest bracket cost when no overflow specified", () => {
      const calcNoOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 3000, costCents: 900 },
      ]);
      expect(
        calcNoOverflow.computeShippingCents([makeLine("a", 1, 5000)], 5000),
      ).toBe(900);
    });

    it("sums weights across multiple lines", () => {
      // 2 items × 300g = 600g → second bracket (upTo 2000)
      const lines = [
        makeLine("a", 2, 300),
      ];
      expect(calc.computeShippingCents(lines, 5000)).toBe(700);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      expect(
        unordered.computeShippingCents([makeLine("a", 1, 400)], 5000),
      ).toBe(300);
    });
  });
});

