toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

function makeLine(
  id: string,
  quantity: number,
  weightGrams?: number,
): CartLine {
  return {
    product: { id, name: id, unitPriceCents: 1000, weightGrams },
    quantity,
  };
}

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for any lines", () => {
    expect(calc.computeShippingCents([makeLine("a", 1)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(9.99)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 49.99)).toThrow(RangeError);
    });

    it("accepts 0 flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts 0 freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine("a", 1)], 2000)).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal meets the free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 1)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds the free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 1)], 6000)).toBe(0);
    });

    it("returns flat fee when subtotal is below the free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 1)], 4999)).toBe(599);
    });

    it("charges flat fee when freeOverCents is undefined", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine("a", 1)], 999999)).toBe(599);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: -1, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            9.99,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      1800,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1)], 5000),
      ).toBe(0);
    });

    it("selects the first bracket that covers the weight", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1, 400)], 5000),
      ).toBe(300);
    });

    it("handles exact bracket boundary", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1, 500)], 5000),
      ).toBe(300);
    });

    it("moves to next bracket when weight exceeds current", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1, 501)], 5000),
      ).toBe(700);
    });

    it("selects highest bracket at its boundary", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1, 5000)], 5000),
      ).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1, 6000)], 5000),
      ).toBe(1800);
    });

    it("defaults to heaviest bracket cost when no overflow specified", () => {
      const calcNoOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 3000, costCents: 900 },
      ]);
      expect(
        calcNoOverflow.computeShippingCents([makeLine("a", 1, 5000)], 5000),
      ).toBe(900);
    });

    it("sums weights across multiple lines", () => {
      // 2 items × 300g = 600g → second bracket (upTo 2000)
      const lines = [
        makeLine("a", 2, 300),
      ];
      expect(calc.computeShippingCents(lines, 5000)).toBe(700);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      expect(
        unordered.computeShippingCents([makeLine("a", 1, 400)], 5000),
      ).toBe(300);
    });
  });
});

